// The conversation with the kobold about an exploration: what the person
// says (also while it answers: it joins that answer) and Stop.
import { field } from "../../asked.js";
import { explorationOf } from "./actions.js";
import { attachedIn } from "./person-acts.js";
export function talkRoutes(store, talks, button) {
    const id = (body) => explorationOf(store(), field(body, "id")).id;
    return {
        "POST /api/kobble/explorations/say": button((body) => {
            void talks.say(id(body), field(body, "text"), attachedIn(body), spokenIn(body));
        }),
        "POST /api/kobble/explorations/stop": button((body) => {
            talks.talk(id(body)).stop();
        }),
    };
}
// The language the person spoke in, when they talked instead of typing.
function spokenIn(body) {
    const value = body?.spokenIn;
    return typeof value === "string" && value.trim() ? value : undefined;
}
